steps.solution:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  type = string
}

resource "aws_s3_bucket" "logs" {
  bucket = "acme-logs-${var.environment}"
  tags = {
    Environment = var.environment
  }
}

output "bucket_arn" {
  value = aws_s3_bucket.logs.arn
}
